180	    @DisplayName("同设备并发申请：半开窗口冲突在真实并发下仍只放行一个（设备行锁串行）")
181	    void concurrentOverlappingRequestsOnlyOneAccepted() throws Exception {
182	        LocalDateTime s = BASE.plusDays(1);
183	        LocalDateTime e = s.plusHours(2);
184	
185	        ExecutorService pool = Executors.newFixedThreadPool(2);
186	        CountDownLatch start = new CountDownLatch(1);
