189	            for (String id : new String[]{"R-C1", "R-C2"}) {
190	                futures.add(pool.submit(() -> {
191	                    start.await();
192	                    return service.create(new CreateCutoverRequest(
193	                            id, "割接-" + id, DEVICE_SW1, Priority.MEDIUM, s, e,
194	                            steps("s1", "NORMAL")));
195	                }));
196	            }
197	            start.countDown();
198	
199	            ActionResult r1 = futures.get(0).get(30, TimeUnit.SECONDS);
200	            ActionResult r2 = futures.get(1).get(30, TimeUnit.SECONDS);
201	            long submitted = java.util.stream.Stream.of(r1, r2)
202	                    .filter(r -> "SUBMITTED".equals(r.request().status())).count();
203	            long rejected = java.util.stream.Stream.of(r1, r2)
